document.addEventListener('DOMContentLoaded', () => {
    const btnRegistrarVenta = document.getElementById('registrarVenta');
    const btnBuscarVenta = document.getElementById('buscarVenta');
    const seccionRegistrarVenta = document.querySelector('.contenidoRegistrarVenta');
    const seccionListaVenta = document.querySelector('.contenidoListaVenta');

    if (btnRegistrarVenta) {
        btnRegistrarVenta.addEventListener('click', (e) => {
            e.preventDefault();
            seccionRegistrarVenta.classList.remove('hidden');
            seccionListaVenta.classList.add('hidden');
            cargarClientes();
            cargarProductos();
            obtenerUltimosNumeros();
            document.getElementById('fechaHoraVenta').value = new Date().toLocaleString();
        });
    }

    if (btnBuscarVenta) {
        btnBuscarVenta.addEventListener('click', (e) => {
            e.preventDefault();
            seccionRegistrarVenta.classList.add('hidden');
            seccionListaVenta.classList.remove('hidden');
            listarVentas();
        });
    }
});

// VARIABLES GLOBALES
let listaDetallesVenta = [];

function cargarClientes() {
    fetch('C_Logica/logica_ventas.php?action=clientes')
        .then(res => res.json())
        .then(data => {
            const select = document.getElementById('cliente');
            select.innerHTML = '<option value="">Seleccione</option>';
            data.forEach(c => {
                const option = document.createElement('option');
                option.value = c.id_cliente;
                option.text = c.nombre;
                select.appendChild(option);
            });
        });
}

function cargarProductos() {
    fetch('C_Logica/logica_ventas.php?action=productos')
        .then(res => res.json())
        .then(data => {
            window.productosVenta = data;
        });
}

// AUTOCOMPLETADO PRODUCTO
const inputProducto = document.getElementById('productoBuscarVenta');
if (inputProducto) {
    inputProducto.addEventListener('input', function () {
        const input = this.value.toLowerCase();
        if (window.productosVenta) {
            const resultado = window.productosVenta.find(p => p.nombre.toLowerCase().includes(input));
            if (resultado) {
                document.getElementById('idProductoSeleccionadoVenta').value = resultado.id_producto;
                document.getElementById('precioVentaDetalleVenta').value = resultado.precio;
            }
        }
    });
}

// AGREGAR DETALLE
const btnAgregar = document.getElementById('btnAgregarDetalleVenta');
if (btnAgregar) {
    btnAgregar.addEventListener('click', () => {
        const id = document.getElementById('idProductoSeleccionadoVenta').value;
        const nombre = document.getElementById('productoBuscarVenta').value;
        const cantidad = parseFloat(document.getElementById('cantidadDetalleVenta').value);
        const precio = parseFloat(document.getElementById('precioVentaDetalleVenta').value);
        const descuento = parseFloat(document.getElementById('descuentoDetalleVenta').value);

        if (id && nombre && cantidad > 0 && precio > 0) {
            listaDetallesVenta.push({ id_producto: id, nombre, cantidad, precio_venta: precio, descuento });
            renderTablaDetalle();
        }
    });
}

function renderTablaDetalle() {
    const tbody = document.querySelector('.tbodyDetallesVenta');
    tbody.innerHTML = '';
    let total = 0;
    let impuesto = parseFloat(document.getElementById('impuestoVenta').value || 0);
    listaDetallesVenta.forEach((d, i) => {
        const subtotal = d.cantidad * d.precio_venta - d.descuento;
        total += subtotal;
        const row = `<tr>
            <td>${d.nombre}</td><td>${d.cantidad}</td><td>${d.precio_venta}</td><td>${d.descuento}</td>
            <td>${subtotal.toFixed(2)}</td>
            <td><button onclick="quitarDetalle(${i})">Quitar</button></td>
        </tr>`;
        tbody.innerHTML += row;
    });
    document.getElementById('totalVenta').textContent = total.toFixed(2);
    document.getElementById('impuestoVentaTotal').textContent = (total * impuesto / 100).toFixed(2);
}

function quitarDetalle(index) {
    listaDetallesVenta.splice(index, 1);
    renderTablaDetalle();
}

// FORMULARIO REGISTRO DE VENTA
const form = document.getElementById('FormRegistrarVenta');
if (form) {
    form.addEventListener('submit', e => {
        e.preventDefault();

        const venta = {
            tipoComprobante: document.getElementById('tipoComprobanteVenta').value,
            serie_Comprobante: document.getElementById('serieComprobanteVenta').value,
            numComprobante: document.getElementById('numComprobanteVenta').value,
            fechaHora: document.getElementById('fechaHoraVenta').value,
            impuesto: parseFloat(document.getElementById('impuestoVenta').value),
            total_venta: parseFloat(document.getElementById('totalVenta').textContent),
            id_cliente: document.getElementById('cliente').value,
            id_empleado: document.getElementById('idEmpleadoLogueadoVenta').value,
            estado: 1,
            detalles: listaDetallesVenta
        };

        fetch('C_Logica/logica_ventas.php', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(venta)
        }).then(res => res.json())
            .then(data => {
                alert('Venta registrada correctamente');
                listaDetallesVenta = [];
                renderTablaDetalle();
            });
    });
}

function obtenerUltimosNumeros() {
    fetch('C_Logica/logica_ventas.php?action=ultimos')
        .then(res => res.json())
        .then(data => {
            const tipo = document.getElementById('tipoComprobanteVenta').value;
            let ult = 0;
            if (data[tipo] && data[tipo][0] && data[tipo][0].ultimo_numero) {
                ult = data[tipo][0].ultimo_numero;
            }
            const nuevoNumero = parseInt(ult) + 1;
            document.getElementById('serieComprobanteVenta').value = tipo === 'Factura' ? 'F001' : 'B001';
            document.getElementById('numComprobanteVenta').value = nuevoNumero.toString().padStart(6, '0');
        });
}


function listarVentas() {
    fetch('C_Logica/logica_ventas.php?action=listar')
        .then(res => res.json())
        .then(ventas => {
            const tbody = document.querySelector('.tbodyVentas');
            tbody.innerHTML = '';
            ventas.forEach(v => {
                const row = `<tr>
                    <td>${v.id_venta}</td>
                    <td>${v.ClienteNombre}</td>
                    <td>${v.tipoComprobante} ${v.serie_Comprobante}-${v.numComprobante}</td>
                    <td>${v.fechaHora}</td>
                    <td>${v.total_venta}</td>
                    <td><button onclick="verDetalleVenta(${v.id_venta})">Ver Detalle</button></td>
                </tr>`;
                tbody.innerHTML += row;
            });
        });
}

function verDetalleVenta(id) {
    fetch(`C_Logica/logica_ventas.php?action=obtener&id=${id}`)
        .then(res => res.json())
        .then(data => {
            const tbody = document.getElementById('detalleVentaBody');
            tbody.innerHTML = '';
            data.detalles.forEach(d => {
                const subtotal = d.cantidad * d.precio_venta - d.descuento;
                tbody.innerHTML += `<tr>
                    <td>${d.nombre}</td><td>${d.cantidad}</td><td>${d.precio_venta}</td>
                    <td>${d.descuento}</td><td>${subtotal.toFixed(2)}</td>
                </tr>`;
            });
            document.getElementById('modalDetalleVenta').showModal();
        });
}

const btnCerrarDetalle = document.getElementById('btnCerrarDetalleVenta');
if (btnCerrarDetalle) {
    btnCerrarDetalle.addEventListener('click', () => {
        document.getElementById('modalDetalleVenta').close();
    });
}
